WITH filtered AS (SELECT *, DATE_ADD(shipped_date, 76) AS shipped_date_plus_76d, CASE WHEN status IN ('DELIVERED', 'RETURNED') THEN 'Group A' ELSE 'Other' END AS status_group FROM shipments WHERE carrier IS NOT NULL) SELECT src.id, src.order_id, src.carrier, src.delivered_date, src.status, src.shipped_date_plus_76d, o.shipping_fee, o.status AS order_status, o.amount FROM filtered src INNER JOIN orders o ON src.order_id <=> o.id
